PREFIX brick: <http://brickschema.org/brick#>
PREFIX ref: <http://w3id.org/brick/example/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?z ?lbl ?p ?o
WHERE {
  ?z a brick:Zone .
  FILTER(str(?z) LIKE "%Perimeter_top_ZN_4%")
  ?z rdfs:label ?lbl .
  OPTIONAL {?p brick:hasLocation ?z . ?p a brick:ElectricPowerSensor . ?p ref:hasTimeseriesId ?pid .}
  OPTIONAL {?o brick:hasLocation ?z . ?o a brick:OccupancySensor . ?o ref:hasTimeseriesId ?oid .}
}

